package com.mavric.health.patients.application;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.ObjectMapper;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.*;
import com.mavric.health.shared.*;
import com.mavric.health.patients.domain.Requests.Patient;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real service/store with mock servlet request and modeled executor/transactions; no HTTP or DB integration. */
class PatientServiceSqlServerTest {
 static final String ID="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",PATIENT="cc000000-0000-4000-8000-000000000001";
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final Access access=mock(Access.class);final Sql sql=mock(Sql.class);final ObjectMapper mapper=new ObjectMapper();final PatientService service=new PatientService(new SqlServerPatientStore(executor,manager,mapper),access,mapper);final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/patients");
 PatientServiceSqlServerTest(){when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ID,c.actorId());assertEquals(TENANT,c.tenantId());var row=patient();var tenant=(TenantRef)request.getAttribute("health.tenant");row.put("domain",tenant.domain());if(inv.getArgument(0)==SqlServerProcedure.PATIENT_SAVE){Object[] a=(Object[])inv.getRawArguments()[2];row.put("id",a[0]);row.put("revision",(Integer)a[2]==0?1:6);var json=mapper.readValue((String)a[1],Map.class);for(String key:List.of("name","identifier","birthDate","species","contact","allergies"))row.put(key,json.get(key));}return new SqlServerExecutor.Result(List.of(List.of(row)),List.of());});}
 void actor(String role,boolean platform,String domain,String status,List<String> modules){request.setAttribute("health.requestId",ID);var a=new Actor(ID,"Synthetic","qa@example.test",platform?null:TENANT,List.of(role),"a".repeat(64));doReturn(a).when(access).actor();request.setAttribute("health.actor",a);if(platform)request.removeAttribute("health.tenant");else request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic",domain.equals("ANIMAL")?"VETERINARY":"DOCTOR",domain,status,modules));TraceContext.REQUEST.set(request);}
 static Map<String,Object> patient(){var r=new LinkedHashMap<String,Object>();r.put("id",PATIENT);r.put("tenantId",TENANT);r.put("name","Synthetic patient");r.put("domain","HUMAN");r.put("identifier","SYN-001");r.put("birthDate",null);r.put("species",null);r.put("contact",Map.of());r.put("allergies",List.of());r.put("revision",1);r.put("createdAt","2026-11-04T00:00:00.123456Z");return r;}
 static Patient input(String domain){return new Patient("Synthetic patient",domain,"SYN-001",null,domain.equals("ANIMAL")?"synthetic-species":null,Map.of(),Set.of());}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void allReadRolesAndOnlyWriteRolesUseTypedSpWithoutBranchNarrowing(){for(String role:List.of("ADM","REC","PRO","ASI","AUD")){actor(role,false,"HUMAN","ACTIVE",List.of("CORE"));assertEquals(11,service.list(null,1,-1).getFirst().size());assertEquals(11,service.get(PATIENT).size());if(List.of("ADM","REC","PRO").contains(role))assertEquals(11,service.save(null,input("HUMAN"),0).size());else assertEquals(403,assertThrows(ApiException.class,()->service.save(null,input("HUMAN"),0)).status);}verify(access,times(10)).roles("ADM","REC","PRO","ASI","AUD");verify(access,times(3)).write("CORE","ADM","REC","PRO");verify(access,never()).branch(anyString());verify(executor,times(5)).execute(eq(SqlServerProcedure.PATIENTS_LIST),any(),eq(""),eq(1),eq(0));verify(executor,times(5)).execute(eq(SqlServerProcedure.PATIENT_GET),any(),eq(PATIENT));verify(executor,times(3)).execute(eq(SqlServerProcedure.PATIENT_SAVE),any(),anyString(),anyString(),eq(0));verifyNoInteractions(sql);}
 @Test void hostRequestAndActorGuardsPreventAnySp(){assertEquals(500,assertThrows(ApiException.class,()->service.get(PATIENT)).status);actor("ADM",false,"HUMAN","ACTIVE",List.of("CORE"));doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,()->service.get(PATIENT)).status);actor("SAD",true,"HUMAN","ACTIVE",List.of("CORE"));assertEquals(403,assertThrows(ApiException.class,()->service.list("",1,0)).status);actor("PAC",false,"HUMAN","ACTIVE",List.of("CORE"));assertEquals(403,assertThrows(ApiException.class,()->service.get(PATIENT)).status);actor("ADM",false,"HUMAN","ACTIVE",List.of("CORE"));request.setAttribute("health.actor","forged");assertEquals(403,assertThrows(ApiException.class,()->service.get(PATIENT)).status);actor("ADM",false,"HUMAN","ACTIVE",List.of("CORE"));request.setAttribute("health.tenant",new TenantRef(ID,"Other","other","DOCTOR","HUMAN","ACTIVE",List.of("CORE")));assertEquals(403,assertThrows(ApiException.class,()->service.get(PATIENT)).status);request.setAttribute("health.tenant","bad");assertEquals(500,assertThrows(ApiException.class,()->service.get(PATIENT)).status);verifyNoInteractions(executor,sql);}
 @Test void writeRequiresActiveCoreEvenWhenAccessIsModeledAndNoClientAuthority(){actor("ADM",false,"HUMAN","SUSPENDED",List.of("CORE"));assertEquals("SUSPENDED",assertThrows(ApiException.class,()->service.save(null,input("HUMAN"),0)).code);actor("ADM",false,"HUMAN","ACTIVE",List.of());assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,()->service.save(null,input("HUMAN"),0)).code);verifyNoInteractions(executor,sql);actor("REC",false,"ANIMAL","ACTIVE",List.of("CORE"));request.addHeader("X-Roles","SAD");request.addHeader("X-Tenant-Id",ID);request.setContent("forged body authority".getBytes());assertEquals("ANIMAL",service.save(null,input("ANIMAL"),0).get("domain"));verify(executor,times(1)).execute(eq(SqlServerProcedure.PATIENT_SAVE),argThat(c->c.tenantId().equals(TENANT)&&c.roles().equals(List.of("REC"))),anyString(),anyString(),eq(0));}
 @Test void saveUsesReturnedRevisionAndNoPreGetOrPostGet(){actor("PRO",false,"HUMAN","ACTIVE",List.of("CORE"));var out=service.save(PATIENT,input("HUMAN"),5);assertEquals(6,out.get("revision"));assertEquals(PATIENT,out.get("id"));verify(executor,times(1)).execute(eq(SqlServerProcedure.PATIENT_SAVE),any(),eq(PATIENT),anyString(),eq(5));verify(executor,never()).execute(eq(SqlServerProcedure.PATIENT_GET),any(),any(Object[].class));verifyNoInteractions(sql);}
 @Test void linkAndHistoryRejectAuthorityAndInvalidInputsBeforePersistence(){assertEquals(500,assertThrows(ApiException.class,()->service.link(null,null)).status);assertEquals(500,assertThrows(ApiException.class,()->service.history(null)).status);actor("PRO",false,"HUMAN","ACTIVE",List.of("PORTAL"));assertEquals(403,assertThrows(ApiException.class,()->service.link(null,null)).status);actor("REC",false,"HUMAN","ACTIVE",List.of("PORTAL"));assertEquals(403,assertThrows(ApiException.class,()->service.history(null)).status);assertEquals(400,assertThrows(ApiException.class,()->service.link(PATIENT,null)).status);actor("PRO",false,"HUMAN","ACTIVE",List.of());assertEquals(400,assertThrows(ApiException.class,()->service.history("bad")).status);verifyNoInteractions(sql,executor);}
 @Test void safeSpFailureDoesNotFallbackOrExposeDriver(){actor("REC",false,"HUMAN","ACTIVE",List.of("CORE"));doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,51003))).when(executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->service.save(PATIENT,input("HUMAN"),1));assertEquals(409,e.status);assertFalse(e.toString().contains("private"));assertEquals("rollback",manager.events.getLast());verify(executor,times(1)).execute(any(),any(),any(Object[].class));verifyNoInteractions(sql);}
 @Test void minimalSpringKeepsLegacyConstructorAndLegacyDoesNotUseStore(){when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());try(var c=new AnnotationConfigApplicationContext()){c.registerBean(Sql.class,()->sql);c.registerBean(Access.class,()->access);c.registerBean(ObjectMapper.class,()->mapper);c.registerBean(PatientService.class);c.refresh();assertEquals(List.of(),c.getBean(PatientService.class).list("synthetic",1,0));verify(sql).rows(anyString(),any(Object[].class));verify(access).roles("ADM","REC","PRO","ASI","AUD");assertEquals(0,c.getBeanNamesForType(SqlServerPatientStore.class).length);assertEquals(0,c.getBeanNamesForType(javax.sql.DataSource.class).length);}verifyNoInteractions(executor);}

 static com.mavric.health.patients.domain.Requests.Link linkInput(){return new com.mavric.health.patients.domain.Requests.Link("dd000000-0000-4000-8000-000000000001",1,null,false,null);}
 void linkAndHistoryResults(){when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(TENANT,c.tenantId());assertEquals(ID,c.actorId());Object[] a=(Object[])inv.getRawArguments()[2];assertEquals(PATIENT,a[0]);if(inv.getArgument(0)==SqlServerProcedure.PATIENT_LINK_SAVE){assertEquals(2,a.length);var json=mapper.readValue((String)a[1],Map.class);var row=new LinkedHashMap<String,Object>();row.put("tenantId",TENANT);row.put("patientId",PATIENT);for(String key:List.of("userId","active"))row.put(key,json.get(key));row.put("revision",(Integer)json.get("expectedRevision")+1);return new SqlServerExecutor.Result(List.of(List.of(row)),List.of());}assertEquals(SqlServerProcedure.PATIENT_HISTORY,inv.getArgument(0));assertEquals(1,a.length);return new SqlServerExecutor.Result(List.of(List.of(),List.of(),List.of(),List.of(Map.of("patientId",PATIENT,"encountersLimit",200,"entriesLimit",1000,"documentsLimit",200))),List.of());});}
 @Test void linkOnlyAdmRecPortalAndHistoryOnlyProAsiAudWithNoGetOrAuditExtra(){linkAndHistoryResults();for(String role:List.of("ADM","REC")){actor(role,false,"HUMAN","ACTIVE",List.of("PORTAL"));var out=service.link(PATIENT,linkInput());assertEquals(5,out.size());assertEquals(false,out.get("active"));assertFalse(out.toString().contains("private"));assertEquals(403,assertThrows(ApiException.class,()->service.history(PATIENT)).status);}for(String role:List.of("PRO","ASI","AUD")){actor(role,false,"HUMAN","SUSPENDED",List.of());var out=service.history(PATIENT);assertEquals(5,out.size());assertEquals(Map.of("encounters",200,"entries",1000,"documents",200),out.get("limits"));assertEquals(403,assertThrows(ApiException.class,()->service.link(PATIENT,linkInput())).status);}verify(access,times(2)).write("PORTAL","ADM","REC");verify(access,times(3)).roles("PRO","ASI","AUD");verify(executor,times(2)).execute(eq(SqlServerProcedure.PATIENT_LINK_SAVE),any(),eq(PATIENT),anyString());verify(executor,times(3)).execute(eq(SqlServerProcedure.PATIENT_HISTORY),any(),eq(PATIENT));verify(executor,times(5)).execute(any(),any(),any(Object[].class));verify(access,never()).link(anyString(),anyString());verify(access,never()).branch(anyString());verifyNoInteractions(sql);}
 @Test void linkSuspensionPortalGuardAndHistoryAnimalUnrestrictedRead(){linkAndHistoryResults();actor("REC",false,"HUMAN","ACTIVE",List.of("CORE"));assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,()->service.link(PATIENT,linkInput())).code);actor("ADM",false,"HUMAN","SUSPENDED",List.of("PORTAL"));assertEquals("SUSPENDED",assertThrows(ApiException.class,()->service.link(PATIENT,linkInput())).code);verifyNoInteractions(executor);actor("AUD",false,"ANIMAL","SUSPENDED",List.of());assertEquals(PATIENT,service.history(PATIENT).get("patientId"));verify(executor,times(1)).execute(eq(SqlServerProcedure.PATIENT_HISTORY),any(),eq(PATIENT));}
 @Test void linkHistoryInternalAuthority401AndPlatformForeignHostStopBeforeSp(){actor("ADM",false,"HUMAN","ACTIVE",List.of("PORTAL"));doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,()->service.link(PATIENT,linkInput())).status);actor("SAD",true,"HUMAN","ACTIVE",List.of("PORTAL"));assertEquals(403,assertThrows(ApiException.class,()->service.history(PATIENT)).status);actor("PRO",false,"HUMAN","ACTIVE",List.of());request.setAttribute("health.tenant",new TenantRef(ID,"Other","other","DOCTOR","HUMAN","ACTIVE",List.of()));assertEquals(403,assertThrows(ApiException.class,()->service.history(PATIENT)).status);actor("REC",false,"HUMAN","ACTIVE",List.of("PORTAL"));request.setAttribute("health.actor","forged");assertEquals(403,assertThrows(ApiException.class,()->service.link(PATIENT,linkInput())).status);verifyNoInteractions(sql,executor);}
 @Test void linkHistoryError404AndCommitFailureDoNotFallbackOrAddQueries(){actor("REC",false,"HUMAN","ACTIVE",List.of("PORTAL"));doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,51002))).when(executor).execute(any(),any(),any(Object[].class));assertEquals(404,assertThrows(ApiException.class,()->service.link(PATIENT,linkInput())).status);actor("PRO",false,"HUMAN","ACTIVE",List.of());assertEquals(404,assertThrows(ApiException.class,()->service.history(PATIENT)).status);linkAndHistoryResults();manager.failCommit=true;var e=assertThrows(ApiException.class,()->service.history(PATIENT));assertEquals(500,e.status);assertFalse(e.toString().contains("private"));verify(executor,times(3)).execute(any(),any(),any(Object[].class));verifyNoInteractions(sql);}

 @Test void linksSqlOnlyReadOnSuspendedHumanAnimalAndNoWriteGuard(){request.setAttribute("health.requestId",ID);doAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(SqlServerProcedure.PATIENT_LINKS_LIST,inv.getArgument(0));return new SqlServerExecutor.Result(List.of(List.of()),List.of());}).when(executor).execute(any(),any(),any(Object[].class));for(String role:List.of("ADM","REC"))for(String domain:List.of("HUMAN","ANIMAL")){actor(role,false,domain,"SUSPENDED",List.of());assertEquals(List.of(),service.links(PATIENT,50,0));}verify(executor,times(4)).execute(eq(SqlServerProcedure.PATIENT_LINKS_LIST),any(),eq(PATIENT),eq(50),eq(0));verify(access,never()).write(anyString(),any(String[].class));verifyNoInteractions(sql);var legacy=new PatientService(sql,access,mapper);assertEquals("DATABASE_ERROR",assertThrows(ApiException.class,()->legacy.links(PATIENT,50,0)).code);verifyNoInteractions(sql);}
 @Test void linksAccessMustMatchRequestAndHostAndRejectMixedPortalRoles(){request.setAttribute("health.requestId",ID);for(var roles:List.of(List.of("ADM","PAC"),List.of("REC","RES"),List.of("ADM","SAD"),List.of("REC","SOP"),List.of("PAC"),List.of("RES"),List.of("PRO"),List.of("AUD"))){actor("ADM",false,"HUMAN","ACTIVE",List.of());var a=new Actor(ID,"Synthetic","qa@example.test",TENANT,roles,"a".repeat(64));doReturn(a).when(access).actor();request.setAttribute("health.actor",a);assertEquals(403,assertThrows(ApiException.class,()->service.links(PATIENT,50,0)).status);}actor("ADM",false,"HUMAN","ACTIVE",List.of());request.setAttribute("health.actor",new Actor(TENANT,"Synthetic","qa@example.test",TENANT,List.of("ADM"),"a".repeat(64)));assertEquals(403,assertThrows(ApiException.class,()->service.links(PATIENT,50,0)).status);actor("REC",true,"HUMAN","ACTIVE",List.of());assertEquals(403,assertThrows(ApiException.class,()->service.links(PATIENT,50,0)).status);actor("ADM",false,"HUMAN","ACTIVE",List.of());doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,()->service.links(PATIENT,50,0)).status);verifyNoInteractions(executor,sql);}
}
